from solution import clamp
import unittest

class TestClamp(unittest.TestCase):
    def test_inside(self):
        self.assertEqual(clamp(3, 1, 5), 3)

from solution import unique
import unittest

class TestUnique(unittest.TestCase):
    def test_order(self):
        self.assertEqual(unique([3, 1, 3, 2]), [3, 1, 2])

from solution import parse_bool
import unittest

class TestBool(unittest.TestCase):
    def test_false(self):
        self.assertFalse(parse_bool('false'))

from solution import mean
import unittest

class TestMean(unittest.TestCase):
    def test_fraction(self):
        self.assertEqual(mean([1, 2]), 1.5)

from solution import chunks
import unittest

class TestChunks(unittest.TestCase):
